const CSV_HEADER = 'sku,name,price'

function csvField(value) {
  const text = String(value)
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text
}

function productToCsv(product) {
  const row = [product.sku, product.name, product.price].map(csvField).join(',')
  return `${CSV_HEADER}\n${row}\n`
}

function isInCategory(product, path) {
  return product.category === path || product.category.startsWith(`${path}/`)
}

export function createApp() {
  const app = express()
  app.disable('x-powered-by')
  app.use(express.json({ limit: '50kb' }))

  app.get('/api/health', (req, res) => {
    res.json({ ok: true })
  })

  app.get('/api/products', (req, res) => {
    res.json({ products })
  })

  app.get('/api/products/:sku.csv', (req, res) => {
    const product = products.find((p) => p.sku === req.params.sku)
    if (!product) {
      return res.status(404).json({ error: 'not_found' })
    }
    res.type('text/csv').send(productToCsv(product))
  })

  app.get('/api/products/:sku', (req, res) => {
    const product = products.find((p) => p.sku === req.params.sku)
    if (!product) {
      return res.status(404).json({ error: 'not_found' })
    }
    res.json(product)
  })

  app.get('/api/categories/*splat', (req, res) => {
    const path = req.params.splat.join('/')
    if (!categories.includes(path)) {
      return res.status(404).json({ error: 'not_found' })
    }
    res.json({ path, products: products.filter((p) => isInCategory(p, path)) })
  })

